package io.github.astelev.around_planet.gametest;
import io.github.astelev.around_planet.loader.*;
import io.github.astelev.around_planet.compat.*;
import dev.ryanhcode.sable.api.SubLevelAssemblyHelper;
import dev.ryanhcode.sable.api.sublevel.*;
import dev.ryanhcode.sable.api.sublevel.ticket.*;
import dev.ryanhcode.sable.sublevel.ServerSubLevel;
import dev.ryanhcode.sable.sublevel.storage.SubLevelRemovalReason;
import dev.ryanhcode.sable.companion.math.BoundingBox3i;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.block.Blocks;
import org.joml.Vector3d;
import java.util.*;
@net.neoforged.neoforge.gametest.PrefixGameTestTemplate(false)
public final class ShipLoaderGameTests {
 private record Fixture(ServerSubLevel ship,List<ShipLoaderBlockEntity> loaders){}
 private static Fixture create(GameTestHelper h,int offset,int count){var level=h.getLevel();var p=h.absolutePos(new BlockPos(1+offset,2,1));var blocks=new ArrayList<BlockPos>();for(int i=0;i<count;i++){var at=p.offset(i,0,0);level.setBlockAndUpdate(at,ShipLoaderRegistry.BLOCK.get().defaultBlockState());blocks.add(at);}if(count==0){level.setBlockAndUpdate(p,Blocks.IRON_BLOCK.defaultBlockState());blocks.add(p);}var ship=SubLevelAssemblyHelper.assembleBlocks(level,p,blocks,new BoundingBox3i(p.getX(),p.getY(),p.getZ(),p.getX()+Math.max(0,count-1),p.getY(),p.getZ()));var loaders=new ArrayList<ShipLoaderBlockEntity>();for(var at:blocks){var local=ship.logicalPose().transformPositionInverse(new Vector3d(at.getX()+.5,at.getY()+.5,at.getZ()+.5));if(level.getBlockEntity(BlockPos.containing(local.x,local.y,local.z)) instanceof ShipLoaderBlockEntity be)loaders.add(be);}h.assertTrue(loaders.size()==count,"Missing loader in native plot");return new Fixture(ship,List.copyOf(loaders));}
 private static long tickets(ServerSubLevelContainer c,ServerSubLevel ship){return c.collectForceLoadTickets().getOrDefault(ship,Set.of()).stream().filter(t->t.type().equals(ShipLoaderBridge.TICKET)).count();}
 private static void enable(ShipLoaderBlockEntity be,boolean active){be.getLevel().setBlock(be.getBlockPos(),be.getBlockState().setValue(ShipLoaderBlock.ENABLED,active),3);be.changed();}
 @GameTest(template="empty",templateNamespace="around_planet",batch="shipLoaderGraph",timeoutTicks=100)
 public static void loadersKeepRotaryChildrenAndIndependentTickets(GameTestHelper h){h.runAfterDelay(3,()->{var level=h.getLevel();var c=SubLevelContainer.getContainer(level);var a=create(h,0,2);var b=create(h,5,0);var pipe=c.physicsSystem().getPipeline();dev.ryanhcode.sable.api.physics.constraint.PhysicsConstraintHandle joint=null;try{pipe.teleport(a.ship(),new Vector3d(200,800,200),a.ship().logicalPose().orientation());pipe.teleport(b.ship(),new Vector3d(203,800,200),b.ship().logicalPose().orientation());for(var s:List.of(a.ship(),b.ship())){s.updateBoundingBox();s.updateLastPose();pipe.resetVelocity(s);}joint=pipe.addConstraint(a.ship(),b.ship(),new dev.ryanhcode.sable.api.physics.constraint.RotaryConstraintConfiguration(new Vector3d(a.ship().getSelfMassTracker().getCenterOfMass()),new Vector3d(b.ship().getSelfMassTracker().getCenterOfMass()),new Vector3d(0,1,0),new Vector3d(0,1,0)));ShipLoaderBridge.before(c);h.assertTrue(tickets(c,a.ship())==2&&tickets(c,b.ship())==2&&c.collectForceLoadedSubLevels().containsAll(List.of(a.ship(),b.ship())),"Loader did not cover rotary child");
 c.addForceLoadTicket(b.ship(),SubLevelLoadingTicketType.COMMAND_FORCED,net.minecraft.util.Unit.INSTANCE);enable(a.loaders().getFirst(),false);h.assertTrue(tickets(c,a.ship())==1&&tickets(c,b.ship())==1,"One disabled loader removed another loader");enable(a.loaders().getLast(),false);h.assertTrue(tickets(c,a.ship())==0&&tickets(c,b.ship())==0&&c.collectForceLoadedSubLevels().contains(b.ship()),"Loader removed an unrelated native ticket");enable(a.loaders().getFirst(),true);joint.remove();joint=null;ShipLoaderBridge.before(c);h.assertTrue(tickets(c,a.ship())==1&&tickets(c,b.ship())==0,"Detached child kept loader ticket");
 if(net.neoforged.fml.ModList.get().isLoaded("cruising")){try{double y=(Double)Class.forName("io.github.astelev.cruising.flight.ConnectedFlightAssembly").getMethod("currentMinY",dev.ryanhcode.sable.sublevel.SubLevel.class).invoke(null,a.ship());h.assertTrue(y>356,"Loader disabled Cruising height eligibility");}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
 var be=a.loaders().getFirst();var saved=be.saveWithoutMetadata(level.registryAccess());String id=be.loaderId();be.loadWithComponents(saved,level.registryAccess());h.assertTrue(be.loaderId().equals(id),"Loader identity changed on save");level.removeBlock(be.getBlockPos(),false);ShipLoaderBridge.before(c);h.assertTrue(tickets(c,a.ship())==0,"Broken loader left native ticket");h.succeed();
 }finally{if(joint!=null&&joint.isValid())joint.remove();c.removeForceLoadTicket(b.ship(),SubLevelLoadingTicketType.COMMAND_FORCED,net.minecraft.util.Unit.INSTANCE);for(var s:List.of(a.ship(),b.ship()))if(!s.isRemoved())c.removeSubLevel(s,SubLevelRemovalReason.REMOVED);ShipLoaderBridge.before(c);}});}
 @GameTest(template="empty",templateNamespace="around_planet",batch="shipLoaderDimensions",timeoutTicks=160)
 public static void loaderFollowsDimensionsWithoutLeavingSourceTicket(GameTestHelper h){if(!DimensionalTransfers.available()){h.succeed();return;}h.runAfterDelay(3,()->{var source=h.getLevel();var destination=source.getServer().getLevel(io.github.astelev.around_planet.space.MoonSurface.dimension());var c=SubLevelContainer.getContainer(source);var d=SubLevelContainer.getContainer(destination);var f=create(h,0,1);var id=f.ship().getUniqueId();var be=f.loaders().getFirst();String key=be.loaderId();var pos=be.getBlockPos();try{ShipLoaderBridge.before(c);h.assertTrue(tickets(c,f.ship())==1,"Source ticket missing");for(int x=5;x<=7;x++)for(int z=5;z<=7;z++)destination.getChunk(x,z);DimensionalTransfers.move(List.of(f.ship()),Set.of(),destination,new Vector3d(f.ship().logicalPose().position()),new Vector3d(100,800,100),new org.joml.Quaterniond(),new Vector3d());ShipLoaderBridge.before(c);ShipLoaderBridge.before(d);var moved=(ServerSubLevel)d.getSubLevel(id);h.assertTrue(moved!=null&&tickets(d,moved)==1,"Destination did not inherit loader");var after=(ShipLoaderBlockEntity)destination.getBlockEntity(pos);h.assertTrue(after!=null&&after.loaderId().equals(key),"Dimension transform corrupted loader identity");h.assertTrue(c.getAllTickets().get(id)==null||c.getAllTickets().get(id).tickets().stream().noneMatch(t->t.type().equals(ShipLoaderBridge.TICKET)),"Source loader ticket survived dimensional departure");h.succeed();}finally{for(var container:List.of(c,d)){var ship=container.getSubLevel(id);if(ship!=null)container.removeSubLevel(ship,SubLevelRemovalReason.REMOVED);ShipLoaderBridge.before(container);}}});}
}
